6	export interface GeneratorOptions {
7	  contentDir: string;
8	  outputDir: string;
9	  templatesDir?: string;
10	  layoutsDir?: string;
11	  partialsDir?: string;
12	}
13	
14	export { PageData };
15	
16	export async function generate(options: GeneratorOptions): Promise<void> {
17	  const { contentDir, outputDir } = options;
18	  const templatesDir = options.templatesDir || './templates';
19	  const layoutsDir = options.layoutsDir || './templates/layouts';
20	  const partialsDir = options.partialsDir || './templates/partials';
21	
22	  if (!fs.existsSync(outputDir)) {
23	    fs.mkdirSync(outputDir, { recursive: true });
24	  }
25	
26	  const pluginManager = new PluginManager();
27	  pluginManager.addPlugin(new MarkdownPlugin());
28	  pluginManager.addPlugin(new TemplatePlugin());
29	
30	  const context: BuildContext = {
31	    contentDir,
32	    outputDir,
33	    templatesDir,
34	    layoutsDir,
35	    partialsDir,
36	    pages: []
37	  };
38	
39	  await pluginManager.callHook('onStart', context);
40	  await pluginManager.callHook('beforeBuild', context);
41	
42	  for (const page of context.pages) {
43	    await pluginManager.callHook('onFile', context, page);
44	  }
45	
46	  await pluginManager.callHook('afterBuild', context);
47	  await pluginManager.callHook('onEnd', context);
48	
49	  console.log(`Generated site with ${context.pages.length} page(s) in ${outputDir}`);
50	}
