1	export interface CliArgs {
2	  command: string;
3	  contentDir: string;
4	  outputDir: string;
5	  port?: number;
6	}
7	
8	export function parseArgs(argv: string[]): CliArgs {
9	  const args: CliArgs = {
10	    command: 'build',
11	    contentDir: './content',
12	    outputDir: './dist'
13	  };
14	
15	  for (let i = 0; i < argv.length; i++) {
16	    const arg = argv[i];
17	
18	    if (arg === '--content' && i + 1 < argv.length) {
19	      args.contentDir = argv[++i];
20	    } else if (arg === '--output' && i + 1 < argv.length) {
21	      args.outputDir = argv[++i];
22	    } else if (arg === '--port' && i + 1 < argv.length) {
23	      args.port = parseInt(argv[++i], 10);
24	    } else if (arg === 'build') {
25	      args.command = 'build';
26	    } else if (arg === 'serve') {
27	      args.command = 'serve';
28	    }
29	  }
30	
31	  return args;
32	}
