1	export interface PageData {
2	  slug: string;
3	  filename: string;
4	  content: string;
5	  metadata: Record<string, any>;
6	}
7	
8	export interface BuildContext {
9	  contentDir: string;
10	  outputDir: string;
11	  templatesDir?: string;
12	  layoutsDir?: string;
13	  partialsDir?: string;
14	  pages: PageData[];
15	  [key: string]: any;
16	}
17	
18	export interface Plugin {
19	  name: string;
20	  onStart?(context: BuildContext): Promise<void>;
21	  beforeBuild?(context: BuildContext): Promise<void>;
22	  onFile?(page: PageData, context: BuildContext): Promise<void>;
23	  afterBuild?(context: BuildContext): Promise<void>;
24	  onEnd?(context: BuildContext): Promise<void>;
25	}
26	
27	export class PluginManager {
28	  private plugins: Plugin[] = [];
29	
30	  addPlugin(plugin: Plugin): void {
31	    this.plugins.push(plugin);
32	  }
33	
34	  async callHook(hookName: keyof Plugin, context: BuildContext, page?: PageData): Promise<void> {
35	    for (const plugin of this.plugins) {
36	      const hook = plugin[hookName];
37	      if (typeof hook === 'function') {
38	        if (hookName === 'onFile' && page) {
39	          await (hook as (page: PageData, context: BuildContext) => Promise<void>)(page, context);
40	        } else {
41	          await (hook as (context: BuildContext) => Promise<void>)(context);
42	        }
43	      }
44	    }
45	  }
46	
47	  getPlugins(): Plugin[] {
48	    return this.plugins;
49	  }
50	}
