1	import fs from 'fs';
2	import path from 'path';
3	import { parseMarkdownWithYaml } from '../parser.js';
4	import { Plugin, PageData, BuildContext } from '../plugin.js';
5	
6	function slugFromFilename(filename: string): string {
7	  return filename.replace(/\.md$/, '');
8	}
9	
10	export class MarkdownPlugin implements Plugin {
11	  name = 'markdown';
12	
13	  constructor() {
14	    this.beforeBuild = this.beforeBuild.bind(this);
15	  }
16	
17	  async beforeBuild(context: BuildContext): Promise<void> {
18	    const { contentDir, pages } = context;
19	
20	    if (!fs.existsSync(contentDir)) {
21	      throw new Error(`Content directory not found: ${contentDir}`);
22	    }
23	
24	    const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));
25	
26	    if (files.length === 0) {
27	      throw new Error(`No markdown files found in ${contentDir}`);
28	    }
29	
30	    for (const file of files) {
31	      const filePath = path.join(contentDir, file);
32	      const content = fs.readFileSync(filePath, 'utf-8');
33	      const parsed = await parseMarkdownWithYaml(content);
34	
35	      const page: PageData = {
36	        slug: slugFromFilename(file),
37	        filename: file,
38	        content: parsed.content,
39	        metadata: parsed.metadata
40	      };
41	
42	      pages.push(page);
43	    }
44	  }
45	}
