1	import fs from 'fs';
2	import path from 'path';
3	import { TemplateEngine, createDefaultLayout, createDefaultIndexLayout, createDefaultNavPartial } from '../template.js';
4	import { Plugin, PageData, BuildContext } from '../plugin.js';
5	
6	export class TemplatePlugin implements Plugin {
7	  name = 'template';
8	  private templateEngine: TemplateEngine | null = null;
9	
10	  constructor() {
11	    this.beforeBuild = this.beforeBuild.bind(this);
12	    this.onFile = this.onFile.bind(this);
13	    this.afterBuild = this.afterBuild.bind(this);
14	  }
15	
16	  async beforeBuild(context: BuildContext): Promise<void> {
17	    const { templatesDir = './templates', layoutsDir = './templates/layouts', partialsDir = './templates/partials' } = context;
18	
19	    if (fs.existsSync(templatesDir)) {
20	      this.ensureDefaultTemplates(templatesDir, layoutsDir, partialsDir);
21	      this.templateEngine = new TemplateEngine({
22	        templatesDir,
23	        layoutsDir,
24	        partialsDir
25	      });
26	      context.templateEngine = this.templateEngine;
27	    }
28	  }
29	
30	  async onFile(page: PageData, context: BuildContext): Promise<void> {
31	    const { outputDir } = context;
32	    const html = this.generatePageHtml(page, this.templateEngine);
33	    const outputPath = path.join(outputDir, `${page.slug}.html`);
34	
35	    if (!fs.existsSync(outputDir)) {
36	      fs.mkdirSync(outputDir, { recursive: true });
37	    }
38	
39	    fs.writeFileSync(outputPath, html, 'utf-8');
40	  }
41	
42	  async afterBuild(context: BuildContext): Promise<void> {
43	    const { outputDir, pages } = context;
44	    const html = this.generateIndexHtml(pages, this.templateEngine);
45	    const indexPath = path.join(outputDir, 'index.html');
46	    fs.writeFileSync(indexPath, html, 'utf-8');
47	  }
48	
49	  private generatePageHtml(page: PageData, templateEngine: TemplateEngine | null): string {
50	    const title = page.metadata.title || page.slug;
51	    const layoutName = page.metadata.layout || 'default.hbs';
52	
53	    if (!templateEngine) {
54	      const date = page.metadata.date ? `<p class="date">${page.metadata.date}</p>` : '';
55	      const tags = page.metadata.tags && page.metadata.tags.length > 0
56	        ? `<div class="tags">${page.metadata.tags.map((tag: string) => `<span class="tag">${tag}</span>`).join('')}</div>`
57	        : '';
58	
59	      return `<!DOCTYPE html>
60	<html lang="en">
61	<head>
62	  <meta charset="UTF-8">
63	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
64	  <title>${this.escapeHtml(title)}</title>
65	  <style>
66	    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
67	    a { color: #0066cc; }
68	    .date { color: #666; font-size: 0.9em; }
69	    .tags { margin: 10px 0; }
70	    .tag { display: inline-block; background: #f0f0f0; padding: 2px 8px; margin: 2px; border-radius: 3px; font-size: 0.9em; }
71	    nav { border-bottom: 1px solid #ddd; margin-bottom: 20px; padding-bottom: 10px; }
72	  </style>
73	</head>
74	<body>
75	  <nav>
76	    <a href="index.html">← Home</a>
77	  </nav>
78	  <article>
79	    <h1>${this.escapeHtml(title)}</h1>
80	    ${date}
81	    ${tags}
82	    <div class="content">
83	      ${page.content}
84	    </div>
85	  </article>
86	</body>
87	</html>`;
88	    }
89	
90	    return templateEngine.renderWithLayout(page.content, layoutName, {
91	      title: title,
92	      date: page.metadata.date,
93	      tags: page.metadata.tags || [],
94	      slug: page.slug,
95	      ...page.metadata
96	    });
97	  }
98	
99	  private generateIndexHtml(pages: PageData[], templateEngine: TemplateEngine | null): string {
100	    const sortedPages = pages.sort((a, b) => {
101	      const dateA = new Date(a.metadata.date || '').getTime();
102	      const dateB = new Date(b.metadata.date || '').getTime();
103	      return dateB - dateA;
104	    });
105	
106	    if (!templateEngine) {
107	      const pageLinks = sortedPages
108	        .map((page: PageData) => {
109	          const title = page.metadata.title || page.slug;
110	          const dateStr = page.metadata.date ? ` (${page.metadata.date})` : '';
111	          return `<li><a href="${page.slug}.html">${this.escapeHtml(title)}</a>${dateStr}</li>`;
112	        })
113	        .join('\n    ');
114	
115	      return `<!DOCTYPE html>
116	<html lang="en">
117	<head>
118	  <meta charset="UTF-8">
119	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
120	  <title>Home</title>
121	  <style>
122	    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
123	    a { color: #0066cc; }
124	    li { margin: 8px 0; }
125	  </style>
126	</head>
127	<body>
128	  <h1>Pages</h1>
129	  <ul>
130	    ${pageLinks}
131	  </ul>
132	</body>
133	</html>`;
134	    }
135	
136	    const pageList = sortedPages.map(page => ({
137	      title: page.metadata.title || page.slug,
138	      slug: page.slug,
139	      date: page.metadata.date
140	    }));
141	
142	    return templateEngine.render('index.hbs', 'index.hbs', { pages: pageList });
143	  }
144	
145	  private escapeHtml(text: string): string {
146	    const map: Record<string, string> = {
147	      '&': '&amp;',
148	      '<': '&lt;',
149	      '>': '&gt;',
150	      '"': '&quot;',
151	      "'": '&#039;'
152	    };
153	    return text.replace(/[&<>"']/g, (char: string) => map[char]);
154	  }
155	
156	  private ensureDefaultTemplates(templatesDir: string, layoutsDir: string, partialsDir: string): void {
157	    if (!fs.existsSync(templatesDir)) {
158	      fs.mkdirSync(templatesDir, { recursive: true });
159	    }
160	    if (!fs.existsSync(layoutsDir)) {
161	      fs.mkdirSync(layoutsDir, { recursive: true });
162	    }
163	    if (!fs.existsSync(partialsDir)) {
164	      fs.mkdirSync(partialsDir, { recursive: true });
165	    }
166	
167	    const defaultLayoutPath = path.join(layoutsDir, 'default.hbs');
168	    if (!fs.existsSync(defaultLayoutPath)) {
169	      fs.writeFileSync(defaultLayoutPath, createDefaultLayout(), 'utf-8');
170	    }
171	
172	    const indexLayoutPath = path.join(layoutsDir, 'index.hbs');
173	    if (!fs.existsSync(indexLayoutPath)) {
174	      fs.writeFileSync(indexLayoutPath, createDefaultIndexLayout(), 'utf-8');
175	    }
176	
177	    const indexTemplatePath = path.join(templatesDir, 'index.hbs');
178	    if (!fs.existsSync(indexTemplatePath)) {
179	      fs.writeFileSync(indexTemplatePath, '{{{body}}}', 'utf-8');
180	    }
181	
182	    const navPartialPath = path.join(partialsDir, 'nav.hbs');
183	    if (!fs.existsSync(navPartialPath)) {
184	      fs.writeFileSync(navPartialPath, createDefaultNavPartial(), 'utf-8');
185	    }
186	  }
187	}
