1	import matter from 'gray-matter';
2	import { marked } from 'marked';
3	
4	export interface PageMetadata {
5	  title?: string;
6	  date?: string;
7	  tags?: string[];
8	  template?: string;
9	  layout?: string;
10	  [key: string]: string | string[] | undefined;
11	}
12	
13	export interface ParsedPage {
14	  content: string;
15	  metadata: PageMetadata;
16	}
17	
18	function parseYamlFrontmatter(yamlStr: string): Record<string, string | string[]> {
19	  const result: Record<string, string | string[]> = {};
20	  const lines = yamlStr.trim().split('\n');
21	
22	  for (const line of lines) {
23	    const colonIndex = line.indexOf(':');
24	    if (colonIndex === -1) continue;
25	
26	    const key = line.substring(0, colonIndex).trim();
27	    const value = line.substring(colonIndex + 1).trim();
28	
29	    if (key === 'tags') {
30	      const tags = value.split(',').map(tag => tag.trim()).filter(tag => tag.length > 0);
31	      if (tags.length > 0) {
32	        result[key] = tags;
33	      }
34	    } else if (value.length > 0) {
35	      result[key] = value;
36	    }
37	  }
38	
39	  return result;
40	}
41	
42	export async function parseMarkdown(content: string): Promise<ParsedPage> {
43	  const result = matter(content);
44	
45	  let metadata: PageMetadata = {};
46	
47	  if (typeof result.data === 'object' && result.data !== null) {
48	    metadata = result.data as PageMetadata;
49	  }
50	
51	  const html = await marked.parse(result.content);
52	
53	  return {
54	    content: html,
55	    metadata
56	  };
57	}
58	
59	export async function parseMarkdownWithYaml(content: string): Promise<ParsedPage> {
60	  const fencedRegex = /^---\n([\s\S]*?)\n---\n/;
61	  const match = content.match(fencedRegex);
62	
63	  let metadata: PageMetadata = {};
64	  let markdown = content;
65	
66	  if (match) {
67	    const yamlBlock = match[1];
68	    markdown = content.substring(match[0].length);
69	
70	    const parsedYaml = parseYamlFrontmatter(yamlBlock);
71	    metadata = {
72	      title: parsedYaml.title as string | undefined,
73	      date: parsedYaml.date as string | undefined,
74	      tags: Array.isArray(parsedYaml.tags) ? parsedYaml.tags : undefined,
75	      ...Object.fromEntries(
76	        Object.entries(parsedYaml).filter(([key]) => !['title', 'date', 'tags'].includes(key))
77	      )
78	    };
79	  }
80	
81	  const html = await marked.parse(markdown);
82	
83	  return {
84	    content: html,
85	    metadata
86	  };
87	}
